def aggregate_temperature(reading_list):
    '''
    Takes a list of raw sensor strings. Use parse_sensor_reading to parse each one.
    Collect all temperature values that are not None. Return average of all temperatures
    rounded to 2 decimals. Return 0.0 if no valid temperatures.
    '''
    temps = []
    for reading_str in reading_list:
        result = parse_sensor_reading(reading_str)
        temp = result['temperature']
        if temp is not None:
            temps.append(temp)
    if not temps:
        return 0.0
    average = sum(temps) / len(temps)
    return round(average, 2)


